import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    FaCalendarAlt, FaCheck, FaPlus, FaSync, 
    FaSave, FaComment, FaBullseye, FaTasks, FaSpinner, FaRocket
} from 'react-icons/fa';
import { motion } from 'framer-motion';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [taskNote, setTaskNote] = useState('');
    
    // REAL DATE CALCULATIONS
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();
    const currentWeekDay = today.toLocaleDateString('en-US', { weekday: 'long' });
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];

    const targetDate = new Date(2026, 10, 30);
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));

    useEffect(() => {
        if (user && token) fetchTasks();
    }, [user, token]);

    const fetchTasks = async () => {
        try {
            const res = await axios.get(`http://localhost:8081/api/tasks/user/${user.id}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setTasks(res.data);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const res = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${date.toISOString().split('T')[0]}`,
                {}, { headers: { 'Authorization': `Bearer ${token}` } }
            );
            setTasks([...tasks, res.data]);
            toast.success(`✅ Tasks created for ${monthNames[currentMonth]} ${day}`);
        } catch (error) {
            toast.error('Failed to create tasks');
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const res = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? res.data : t));
            if (updatedTask[field]) {
                toast.success('🤲 Alhamdulillah!');
            } else {
                toast.info('Re-opened task');
            }
        } catch (error) {
            toast.error(`❌ ${error.response?.data?.message || 'Update failed'}`);
        }
    };

    const handleDayClick = async (day) => {
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);
    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        return completed === dayTasks.length ? 'done' : (completed > 0 ? 'partial' : 'started');
    };

    // --- ACTUAL DATA CALCULATIONS ---
    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted).length;
    const progressPercent = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const calculateStreak = () => {
        let streak = 0;
        const sorted = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sorted) {
            if (task.overallCompleted === true) streak++;
            else break;
        }
        return streak;
    };
    const streak = calculateStreak();

    const taskLabels = [
        { key: 'javaCompleted', label: 'Java', icon: '☕' },
        { key: 'leetcodeCompleted', label: 'LeetCode', icon: '💻' },
        { key: 'dsaCompleted', label: 'DSA', icon: '📊' },
        { key: 'sqlCompleted', label: 'SQL/API', icon: '🗄️' },
        { key: 'projectCompleted', label: 'Project', icon: '🚀' },
        { key: 'githubCompleted', label: 'GitHub', icon: '📁' }
    ];

    if (loading) return (
        <div className="flex justify-center items-center h-[60vh]">
            <div className="spinner-border text-primary" role="status" />
        </div>
    );

    return (
        <div className="min-h-screen bg-[#f8fafc] p-6">
            {/* --- TODAY'S REAL DATA HERO HEADER --- */}
            <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className="relative rounded-3xl p-6 text-white mb-6 shadow-xl overflow-hidden"
                style={{ background: 'linear-gradient(135deg, #5b4dd4 0%, #9145f9 50%, #a25bf9 100%)' }}
            >
                <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                    <div className="flex items-start gap-4">
                        <div className="bg-white/20 p-3 rounded-xl backdrop-blur-sm">
                            <FaCalendarAlt size={28} className="text-white" />
                        </div>
                        <div>
                            <h1 className="text-3xl font-bold tracking-tight">Today is</h1>
                            <h2 className="text-4xl font-extrabold mt-1">{currentDay} {monthNames[currentMonth]} {currentYear}</h2>
                            <p className="text-indigo-200 mt-1 font-medium">{currentWeekDay}</p>
                        </div>
                    </div>
                    <div className="text-right bg-white/10 p-4 rounded-2xl backdrop-blur-sm border border-white/10">
                        <p className="text-indigo-200 font-medium text-sm">Days Left to Goal</p>
                        <p className="text-5xl font-extrabold">{daysRemaining}</p>
                        <p className="text-indigo-200 text-xs mt-1">Target: 30 Nov 2026</p>
                    </div>
                </div>
                {/* Abstract blur background shapes */}
                <div className="absolute -top-20 -right-20 w-96 h-96 bg-purple-500 rounded-full blur-[100px] opacity-30" />
                <div className="absolute -bottom-10 -left-10 w-64 h-64 bg-blue-500 rounded-full blur-[80px] opacity-20" />
            </motion.div>

            {/* --- STATS CARDS --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100">
                    <div className="flex justify-between items-start mb-2">
                        <div className="flex items-center gap-2">
                            <div className="bg-purple-100 text-purple-600 p-2 rounded-lg"><FaRocket /></div>
                            <span className="text-sm font-semibold text-gray-700">Overall Progress</span>
                        </div>
                    </div>
                    <h3 className="text-3xl font-bold text-gray-800">{progressPercent}%</h3>
                    <div className="w-full h-1.5 bg-gray-200 rounded-full mt-2">
                        <div className="h-1.5 bg-purple-600 rounded-full" style={{ width: `${progressPercent}%` }} />
                    </div>
                </motion.div>

                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100">
                    <div className="flex justify-between items-start mb-2">
                        <div className="flex items-center gap-2">
                            <div className="bg-green-100 text-green-600 p-2 rounded-lg"><FaTasks /></div>
                            <span className="text-sm font-semibold text-gray-700">Tasks Done</span>
                        </div>
                    </div>
                    <h3 className="text-3xl font-bold text-gray-800">{completedTasks} <span className="text-gray-400 text-lg font-normal">/ {totalTasks}</span></h3>
                    <p className="text-xs text-gray-400 mt-1">Keep going! 🚀</p>
                </motion.div>

                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100">
                    <div className="flex justify-between items-start mb-2">
                        <div className="flex items-center gap-2">
                            <div className="bg-orange-100 text-orange-600 p-2 rounded-lg"><FaCheck /></div>
                            <span className="text-sm font-semibold text-gray-700">Current Streak</span>
                        </div>
                    </div>
                    <h3 className="text-3xl font-bold text-gray-800">{streak} <span className="text-gray-400 text-lg font-normal">Days</span></h3>
                    <p className="text-xs text-green-500 font-medium mt-1">Keep it up! 🔥</p>
                </motion.div>

                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100">
                    <div className="flex justify-between items-start mb-2">
                        <div className="flex items-center gap-2">
                            <div className="bg-blue-100 text-blue-600 p-2 rounded-lg"><FaCalendarAlt /></div>
                            <span className="text-sm font-semibold text-gray-700">Target</span>
                        </div>
                    </div>
                    <h3 className="text-3xl font-bold text-gray-800">{daysRemaining} <span className="text-gray-400 text-lg font-normal">Days</span></h3>
                    <p className="text-xs text-gray-400 mt-1">Stay consistent!</p>
                </motion.div>
            </div>

            {/* --- MAIN GRID: CALENDAR & TODAY'S TASKS --- */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* LEFT COLUMN: CALENDAR */}
                <div className="lg:col-span-2 bg-white rounded-3xl shadow-sm border border-gray-100 p-6">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="font-bold text-lg text-gray-800">📅 Monthly Calendar</h3>
                        <div className="flex gap-2 text-xs">
                            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> Done</span>
                            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-orange-400"></span> Partial</span>
                            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-purple-500"></span> Started</span>
                        </div>
                    </div>

                    <div className="grid grid-cols-7 gap-2 text-center">
                        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
                            <div key={d} className="text-gray-400 text-xs font-semibold py-2">{d}</div>
                        ))}
                        {Array.from({ length: 31 }, (_, i) => i + 1).map((day) => {
                            const status = getDayStatus(day);
                            const isToday = day === currentDay;
                            const bgColor = isToday ? 'bg-purple-600 text-white shadow-md' : 
                                status === 'done' ? 'bg-green-100 text-green-700' :
                                status === 'partial' ? 'bg-orange-100 text-orange-600' :
                                status === 'started' ? 'bg-purple-100 text-purple-600' : 'bg-gray-50 text-gray-400 hover:bg-gray-100';
                            
                            return (
                                <button 
                                    key={day}
                                    onClick={() => handleDayClick(day)}
                                    className={`aspect-square rounded-xl font-medium text-sm transition-all ${bgColor}`}
                                >
                                    {day}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* RIGHT COLUMN: SELECTED DAY TASKS */}
                <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="font-bold text-lg text-gray-800">
                            {selectedDay ? `📋 Day ${selectedDay} Tasks` : 'Select a Day'}
                        </h3>
                        {selectedDay && <span className="text-xs bg-purple-100 text-purple-600 px-3 py-1 rounded-full font-semibold">{getDayTasks(selectedDay).length} Tasks</span>}
                    </div>

                    {selectedDay ? (
                        <div className="space-y-3">
                            {taskLabels.map(({ key, label, icon }) => {
                                const task = getDayTasks(selectedDay)[0];
                                const isCompleted = task ? task[key] : false;
                                return (
                                    <div key={key} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${isCompleted ? 'border-green-200 bg-green-50' : 'border-gray-200 bg-gray-50'}`}>
                                        <div className="flex items-center gap-3">
                                            <span className="text-lg">{icon}</span>
                                            <span className={`text-sm font-medium ${isCompleted ? 'line-through text-green-600' : 'text-gray-700'}`}>{label}</span>
                                        </div>
                                        <button 
                                            onClick={() => task && toggleTask(task.id, key)}
                                            className={`text-xs font-bold px-4 py-1.5 rounded-full transition-colors ${isCompleted ? 'bg-green-500 text-white hover:bg-green-600' : 'bg-purple-500 text-white hover:bg-purple-600'}`}
                                        >
                                            {isCompleted ? '🤲 Done' : 'Mark Done'}
                                        </button>
                                    </div>
                                );
                            })}
                            {getDayTasks(selectedDay).length === 0 && !creating && (
                                <div className="text-center py-10 border-2 border-dashed border-gray-200 rounded-xl bg-gray-50">
                                    <FaPlus className="mx-auto text-gray-400 text-3xl mb-2" />
                                    <p className="text-gray-500 text-sm font-medium">No tasks yet</p>
                                    <button onClick={() => handleDayClick(selectedDay)} className="mt-3 bg-purple-600 text-white text-sm font-semibold px-4 py-2 rounded-full hover:bg-purple-700">
                                        Generate Tasks
                                    </button>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="h-[300px] flex flex-col items-center justify-center text-gray-400">
                            <FaCalendarAlt size={48} className="text-gray-200 mb-3" />
                            <p className="font-medium text-gray-500">👆 Pick a date</p>
                            <p className="text-xs">Track your daily roadmap</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
